window.receiveProjectSource({"path": "test/integration/event_synthesis/test_qa_report_job.py", "lines": ["\"\"\"Integration tests for the daily source-event QA-report job (DAT-7639).", "", "Exercises the REAL sampler SQL (eligibility / create-merge classification /", "joins / ordering / quota+backfill / total-eligible) against seeded accelerate", "rows, plus the full ``_run`` orchestration with the LLM grader canned and S3", "backed by an in-memory fake (so delivery + the rotation-cursor round-trip are", "real code paths without needing localstack).", "", "Prerequisites (operator-managed): a Postgres reachable via ``DB_URL_ACCELERATE``", "with accelerate's ``event_synth`` schema applied (see the module conftest", "preflight). These tests are NOT run in the plan-execution environment (no local", "Postgres); they are authored and gated with Task 8.", "\"\"\"", "", "from __future__ import annotations", "", "import random", "from datetime import UTC, datetime, timedelta", "from decimal import Decimal", "from typing import Any", "from uuid import UUID, uuid4", "", "import pytest", "import structlog", "from accelerate_models.common.models.enum.account_type import AccountType", "from accelerate_models.common.models.enum.entity_directness import EntityDirectness", "from accelerate_models.event_synthesis.app.models.source_event_changes import SourceEventChange", "from accelerate_models.event_synthesis.app.models.source_event_documents import SourceEventDocument", "from accelerate_models.event_synthesis.app.models.source_event_entities import SourceEventEntity", "from sqlalchemy import delete, func, select, text", "", "from common.exceptions import AIServiceException", "from common.exceptions.exceptions import DatabaseReadException", "from common.models.enums import ChatModel", "from db.session_manager_async import sessionmanager_accelerate, sessionmanager_datalake", "from microservices.event_synthesis.cli import qa_report as cli_mod", "from microservices.event_synthesis.config.qa_report import QAReportJobConfig", "from microservices.event_synthesis.observability import metrics as ess_metrics", "from microservices.event_synthesis.repositories.qa_sample import (", "    QASampleRepository,", "    SamplerBudget,", ")", "from microservices.event_synthesis.services.qa_report_llm import QAReportGraderClient", "from microservices.event_synthesis.services.qa_report_types import (", "    QAEventGrade,", "    QAReportDocument,", "    QAReportGradeResult,", "    QAReportOutput,", ")", "from test.integration.event_synthesis.conftest import _InMemoryS3, _use_cfg", "from test.integration.event_synthesis.helpers import (", "    RawEventSeed,", "    cleanup_raw_event_chain,", "    seed_accelerate_source_event,", "    seed_doc_documents,", "    seed_platform_entity,", "    seed_raw_event,", ")", "", "pytestmark = pytest.mark.integration", "", "", "# --------------------------------------------------------------------------- #", "# Config + seed helpers.", "# --------------------------------------------------------------------------- #", "", "", "def _cfg(**overrides: object) -> QAReportJobConfig:", "    base: dict[str, object] = dict(", "        sample_size=10,", "        lookback_days=3650,  # wide window so seeded rows are always eligible", "        merge_min_fraction=0.3,", "        chat_model=ChatModel.GPT_6_LUNA,", "        max_tokens=1024,", "        total_timeout=30.0,", "        fallback_total_timeout=30.0,", "        s3_prefix=\"qa_reports/event_synthesis\",", "        max_summary_chars=2000,", "        max_key_details_chars=2000,", "        max_docs_per_event=5,", "        max_entities_per_event=10,", "        max_changes_per_event=10,", "        max_input_chars=1_000_000,", "        rotation_enabled=False,", "        rotation_wrap=True,", "    )", "    base.update(overrides)", "    return QAReportJobConfig(**base)  # type: ignore[arg-type]", "", "", "def _new_doc_id() -> int:", "    return random.randrange(10**15, 10**16)", "", "", "async def _seed_event(", "    ac: Any,", "    *,", "    category_id: UUID,", "    type_id: UUID,", "    cleanup: dict[str, list[Any]],", "    event_class: str,", "    marker: str,", "    first_detected_on: datetime | None = None,", "    doc_tiers: list[int] | None = None,", ") -> UUID:", "    \"\"\"Seed one active source_event with the create/merge document+change shape.", "", "    ``first_detected_on`` forces a controlled recency value (identical across", "    rows exercises the sampler's ``id DESC`` same-timestamp tiebreak).", "    ``doc_tiers`` seeds one document per given INTEGER ``source_tier`` (real", "    ``doc_info`` shape -- the tier is an int, not a string), overriding the", "    default doc count; use it to exercise the highest-tier-kept trim (F3). Every", "    seeded ``doc.documents`` id is tracked for teardown.", "    \"\"\"", "    event_id = uuid4()", "    cleanup[\"accelerate_source_event_ids\"].append(event_id)", "    await seed_accelerate_source_event(", "        ac,", "        source_event_id=event_id,", "        event_category_id=category_id,", "        event_type_id=type_id,", "        summary=f\"{marker} summary\",", "        key_details={\"qa_seed\": marker},", "        first_detected_on=first_detected_on,", "    )", "    if doc_tiers is None:", "        # source_tier is an INTEGER in production doc_info (1=unverified ..", "        # 5=official); seed it as an int, not the \"1\" string the schema forbids.", "        tiers = [1] * (1 if event_class == \"create\" else 2)", "    else:", "        tiers = doc_tiers", "    for tier in tiers:", "        doc_id = _new_doc_id()", "        cleanup[\"doc_document_ids\"].append(doc_id)", "        await seed_doc_documents(", "            ac,", "            doc_id=doc_id,", "            doc_info={\"source_tier\": tier, \"article_type\": \"news\"},", "            title=f\"{marker} document\",", "        )", "        ac.add(SourceEventDocument(event_id=event_id, document_id=doc_id, raw_event_id=uuid4()))", "    ac.add(", "        SourceEventChange(", "            event_id=event_id,", "            change_type=\"created\",", "            triggering_actor=\"qa-report-test\",", "            change_payload={},", "            materiality_score=Decimal(\"0.500\"),", "            materiality_reasons=[{\"code\": \"seed\"}],", "        )", "    )", "    if event_class == \"merge\":", "        ac.add(", "            SourceEventChange(", "                event_id=event_id,", "                change_type=\"article_linked\",", "                triggering_actor=\"qa-report-test\",", "                change_payload={},", "                materiality_score=Decimal(\"0.500\"),", "                materiality_reasons=[{\"code\": \"seed\"}],", "            )", "        )", "    await ac.commit()", "    return event_id", "", "", "# --------------------------------------------------------------------------- #", "# In-memory S3 + canned grader fixtures.", "# --------------------------------------------------------------------------- #", "", "", "# ``_InMemoryS3``, the ``fake_s3`` fixture and ``_use_cfg`` moved to conftest.py", "# (DAT-8294 plan 03): the entity-plausibility gate needs the same S3 fake, and a", "# second copy of it is the one thing that must not drift -- the gate's copy is what", "# stops a measurement run from writing a real report object or moving the shared", "# rotation cursor.", "", "", "@pytest.fixture", "def canned_grader(monkeypatch: pytest.MonkeyPatch) -> None:", "    \"\"\"Grade every prepared event valid (real prepare_input / from_config kept).\"\"\"", "", "    async def _grade(self: QAReportGraderClient, *, prepared) -> QAReportGradeResult:  # noqa: ANN001", "        per_event = [", "            QAEventGrade(", "                event_id=e.event_id,", "                event_valid=True,", "                merge_correct=None if (e.event_class == \"create\" or len(e.docs) < 2) else True,", "                issues=[],", "                explanation=\"ok\",", "                confidence=0.9,", "                # DAT-8294: the verdict is applicable only where entity identity", "                # actually reached the grader -- null otherwise, exactly as", "                # ``_validate_semantic`` requires of a real response.", "                entity_linkage_plausible=True if e.entities else None,", "                entity_linkage_explanation=None,", "            )", "            for e in prepared.events", "        ]", "        return QAReportGradeResult(", "            output=QAReportOutput(per_event=per_event, duplicate_pairs=[]),", "            chat_model_used=ChatModel.GPT_6_LUNA.value,", "            fallback_used=False,", "        )", "", "    monkeypatch.setattr(QAReportGraderClient, \"grade\", _grade)", "", "", "@pytest.fixture(autouse=True)", "def _keep_shared_session_managers(monkeypatch: pytest.MonkeyPatch) -> None:", "    \"\"\"Stop ``_run`` from tearing down the shared lazy session managers.", "", "    ``_run`` calls ``init/close_session_managers`` in production; in-suite the", "    managers are process-wide singletons other fixtures reuse, so no-op them.", "    \"\"\"", "", "    async def _noop(*_a: Any, **_k: Any) -> None:", "        return None", "", "    monkeypatch.setattr(cli_mod, \"init_session_managers\", _noop)", "    monkeypatch.setattr(cli_mod, \"close_session_managers\", _noop)", "", "", "def _report_documents(store: _InMemoryS3) -> list[QAReportDocument]:", "    # DAT-8141: each run now writes a .html sibling under the same \"/report-\" stem,", "    # so this must select the JSON explicitly rather than by stem alone.", "    return [", "        QAReportDocument.model_validate_json(v)", "        for k, v in store.store.items()", "        if \"/report-\" in k and k.endswith(\".json\")", "    ]", "", "", "def _report_html(store: _InMemoryS3) -> list[str]:", "    return [", "        v.decode(\"utf-8\") if isinstance(v, bytes) else v", "        for k, v in store.store.items()", "        if \"/report-\" in k and k.endswith(\".html\")", "    ]", "", "", "# --------------------------------------------------------------------------- #", "# DAT-10796: the server really cancels a statement at the budget boundary.", "# --------------------------------------------------------------------------- #", "", "", "@pytest.mark.parametrize(\"database\", [\"accelerate\", \"datalake\"])", "async def test_a_statement_past_its_budget_is_cancelled_by_postgres(database: str) -> None:", "    \"\"\"``SET LOCAL statement_timeout`` is honoured on both databases the job reads.", "", "    The unit tests only see the ``SET LOCAL`` text and a simulated SQLSTATE; this", "    proves Postgres actually cancels the statement and that the cancel is", "    classified as ``timeout``. DataLake is covered because the lineage chunks", "    run there under the same budget.", "    \"\"\"", "    manager = sessionmanager_accelerate if database == \"accelerate\" else sessionmanager_datalake", "    budget = SamplerBudget()", "    budget.start(_cfg(sampler_statement_timeout_seconds=1, sampler_budget_seconds=1))", "", "    with structlog.testing.capture_logs() as cap:", "        async with manager.read_session() as session:", "            with pytest.raises(DatabaseReadException, match=\"step slow_probe failed\"):", "                await budget.timed_execute(session, \"slow_probe\", select(func.pg_sleep(5)))", "", "    failed = [e for e in cap if e[\"event\"] == \"ess.qa_report.sample_step_failed\"]", "    assert len(failed) == 1", "    assert failed[0][\"error_kind\"] == \"timeout\"", "    assert failed[0][\"log_level\"] == \"warning\"", "", "", "async def test_detail_fetch_drops_an_event_invalidated_after_the_population_read(", "    cleanup_ess_tables, mirrored_event_type", ") -> None:", "    \"\"\"DAT-10796: the detail fetch re-checks ``status = 'active'`` against Postgres.", "", "    An event that stops being active between the population read and the detail", "    fetch (READ COMMITTED) must not come back, so it drops through the", "    ``sample_detail_missing`` path instead of being graded.", "    \"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        kept = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-details-kept\",", "        )", "        invalidated = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-details-invalidated\",", "        )", "    async with sessionmanager_accelerate.session() as ac:", "        await ac.execute(", "            text(\"UPDATE event_synth.source_events SET status = 'invalidated' WHERE id = :id\"),", "            {\"id\": invalidated},", "        )", "        await ac.commit()", "", "    async with sessionmanager_accelerate.read_session() as ac:", "        repo = QASampleRepository(ac)", "        repo._start_budget(_cfg())", "        details = await repo._load_details([kept, invalidated])", "", "    assert set(details) == {kept}", "", "", "# --------------------------------------------------------------------------- #", "# SQL-backed sampler.", "# --------------------------------------------------------------------------- #", "", "", "async def test_sampler_classifies_create_and_merge(cleanup_ess_tables, mirrored_event_type) -> None:", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        create_id = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-create\",", "        )", "        merge_id = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"merge\",", "            marker=\"qa-merge\",", "        )", "", "    async with sessionmanager_accelerate.read_session() as ac:", "        result = await QASampleRepository(ac).sample_recent(_cfg(sample_size=50), cursor=None)", "", "    by_id = {r.event_id: r.event_class for r in result.rows}", "    assert by_id.get(create_id) == \"create\"", "    assert by_id.get(merge_id) == \"merge\"", "    assert result.total_eligible >= 2", "    assert len(result.rows) <= 50", "", "", "async def test_sampler_both_class_coverage_and_backfill(", "    cleanup_ess_tables, mirrored_event_type", ") -> None:", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        for _ in range(4):", "            await _seed_event(", "                ac,", "                category_id=category_id,", "                type_id=type_id,", "                cleanup=cleanup_ess_tables,", "                event_class=\"create\",", "                marker=\"qa-c\",", "            )", "        for _ in range(4):", "            await _seed_event(", "                ac,", "                category_id=category_id,", "                type_id=type_id,", "                cleanup=cleanup_ess_tables,", "                event_class=\"merge\",", "                marker=\"qa-m\",", "            )", "", "    async with sessionmanager_accelerate.read_session() as ac:", "        result = await QASampleRepository(ac).sample_recent(", "            _cfg(sample_size=6, merge_min_fraction=0.3), cursor=None", "        )", "", "    classes = {r.event_class for r in result.rows}", "    assert classes == {\"create\", \"merge\"}  # >=1 create + >=1 merge", "    assert len(result.rows) <= 6", "    # merge_min_fraction quota: with 4 merges available, sample_size=6 and", "    # fraction=0.3, the merge quota is max(1, round(6*0.3)) = 2, so the blended", "    # sample must carry at least that many merges (not just the mandatory floor", "    # of 1), and still include >=1 create.", "    merge_rows = [r for r in result.rows if r.event_class == \"merge\"]", "    create_rows = [r for r in result.rows if r.event_class == \"create\"]", "    assert len(merge_rows) >= 2", "    assert len(create_rows) >= 1", "", "", "async def test_sampler_single_class_only_creates(cleanup_ess_tables, mirrored_event_type) -> None:", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        for _ in range(3):", "            await _seed_event(", "                ac,", "                category_id=category_id,", "                type_id=type_id,", "                cleanup=cleanup_ess_tables,", "                event_class=\"create\",", "                marker=\"qa-c-only\",", "            )", "", "    with structlog.testing.capture_logs() as cap:", "        async with sessionmanager_accelerate.read_session() as ac:", "            result = await QASampleRepository(ac).sample_recent(_cfg(sample_size=10), cursor=None)", "", "    seeded = {r.event_id for r in result.rows if r.event_class == \"create\"}", "    assert len(seeded) >= 3", "    # No merge seeded in this dataset -> only-create rows for the seeded set.", "    assert all(r.event_class == \"create\" for r in result.rows)", "    # A single populated class emits the single-class signal (create only here).", "    single = [e for e in cap if e.get(\"event\") == \"ess.qa_report.sample_single_class\"]", "    assert single, \"expected an ess.qa_report.sample_single_class log for a create-only dataset\"", "    assert single[-1][\"event_class\"] == \"create\"", "", "", "async def test_sampler_same_first_detected_on_orders_by_id_desc(", "    cleanup_ess_tables, mirrored_event_type", ") -> None:", "    \"\"\"Same ``first_detected_on`` => deterministic ``id DESC`` recency tiebreak.", "", "    This is the load-bearing no-skip invariant called out in the sampler: the", "    ORDER BY, the ``< cursor`` rotation bound, and ``advanced_from`` all use", "    ``(first_detected_on, id)`` with the id tiebreak DESCENDING, so a", "    same-timestamp budget-dropped row can never fall on the wrong side of the", "    watermark and be permanently skipped. Force four rows onto one identical", "    timestamp and assert the SQL returns them strictly ordered by id DESC.", "    \"\"\"", "    category_id, type_id = mirrored_event_type", "    fdo = datetime.now(UTC) - timedelta(hours=1)", "    async with sessionmanager_accelerate.session() as ac:", "        for _ in range(4):", "            await _seed_event(", "                ac,", "                category_id=category_id,", "                type_id=type_id,", "                cleanup=cleanup_ess_tables,", "                event_class=\"create\",", "                marker=\"qa-samets\",", "                first_detected_on=fdo,", "            )", "    seeded = set(cleanup_ess_tables[\"accelerate_source_event_ids\"])", "", "    async with sessionmanager_accelerate.read_session() as ac:", "        result = await QASampleRepository(ac).sample_recent(_cfg(sample_size=50), cursor=None)", "", "    ordered = [r.event_id for r in result.rows if r.event_id in seeded]", "    assert set(ordered) == seeded  # all four selected", "    # UUID canonical-hex ordering == Postgres uuid byte ordering, so a Python", "    # string sort reproduces the SQL ``id DESC`` tiebreak exactly.", "    assert ordered == sorted(seeded, key=str, reverse=True)", "    # All four carry the one identical timestamp we forced (the tie precondition).", "    assert len({r.first_detected_on for r in result.rows if r.event_id in seeded}) == 1", "", "", "async def test_sampler_total_eligible_delta_matches_seeded(", "    cleanup_ess_tables, mirrored_event_type", ") -> None:", "    \"\"\"``total_eligible`` rises by exactly the count of newly-seeded eligible events.", "", "    Measures the delta rather than an absolute count, so it is robust to any", "    pre-existing rows in the long-lived local DB. Every seeded event is active,", "    recent, and has >=1 linked document -> each adds exactly one to the count.", "    \"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.read_session() as ac:", "        before = (await QASampleRepository(ac).sample_recent(_cfg(), cursor=None)).total_eligible", "", "    async with sessionmanager_accelerate.session() as ac:", "        for _ in range(3):", "            await _seed_event(", "                ac,", "                category_id=category_id,", "                type_id=type_id,", "                cleanup=cleanup_ess_tables,", "                event_class=\"create\",", "                marker=\"qa-elig-c\",", "            )", "        for _ in range(2):", "            await _seed_event(", "                ac,", "                category_id=category_id,", "                type_id=type_id,", "                cleanup=cleanup_ess_tables,", "                event_class=\"merge\",", "                marker=\"qa-elig-m\",", "            )", "", "    async with sessionmanager_accelerate.read_session() as ac:", "        after = (await QASampleRepository(ac).sample_recent(_cfg(), cursor=None)).total_eligible", "", "    assert after - before == 5", "", "", "async def test_sampler_keeps_highest_source_tier_docs(", "    cleanup_ess_tables, mirrored_event_type", ") -> None:", "    \"\"\"Doc trim keeps the highest integer ``source_tier`` docs (F1 + F3, end-to-end).", "", "    Seeds one event with five docs of distinct tiers 1..5 through the real", "    ``doc.documents`` JSONB round-trip, caps ``max_docs_per_event`` at 3, and", "    asserts the sampled row keeps tiers ``[5, 4, 3]`` as integers -- proving both", "    that the tier survives as an ``int`` (not the forbidden ``\"1\"`` string, and", "    not degraded to ``None``) and that the trim retains the best evidence.", "    \"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        tier_event_id = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"merge\",", "            marker=\"qa-tier\",", "            doc_tiers=[1, 2, 3, 4, 5],", "        )", "", "    async with sessionmanager_accelerate.read_session() as ac:", "        result = await QASampleRepository(ac).sample_recent(", "            _cfg(sample_size=50, max_docs_per_event=3), cursor=None", "        )", "", "    row = next((r for r in result.rows if r.event_id == tier_event_id), None)", "    assert row is not None, \"seeded tier event was not sampled\"", "    tiers = [d.source_tier for d in row.docs]", "    assert tiers == [5, 4, 3]  # highest-tier docs kept, in descending order", "    assert all(isinstance(t, int) for t in tiers)  # F1: int survives the JSONB read", "", "", "# --------------------------------------------------------------------------- #", "# Full-run happy path.", "# --------------------------------------------------------------------------- #", "", "", "async def test_full_run_delivers_report_covering_three_checks(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, canned_grader, record_metrics", ") -> None:", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-c\",", "        )", "        await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"merge\",", "            marker=\"qa-m\",", "        )", "", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=False, sample_size=50))", "    code = await cli_mod._run()", "", "    assert code == 0", "    docs = _report_documents(fake_s3)", "    assert len(docs) == 1", "    doc = docs[0]", "    # All three checks present: per-event validity + merge_correct, and a", "    # duplicate_pairs array (possibly empty).", "    assert doc.llm_report.per_event", "    assert doc.metadata.out_of_sample_count >= 0", "    assert doc.metadata.chat_model == ChatModel.GPT_6_LUNA.value", "    assert doc.metadata.fallback_used is False", "    # Metadata is internally consistent and reflects both seeded classes.", "    assert doc.metadata.sampled_count == len(doc.sampled_event_ids)", "    assert doc.metadata.create_count >= 1", "    assert doc.metadata.merge_count >= 1", "    # Observability: the job emits a delivered counter and an out-of-sample", "    # gauge whose value equals the persisted metadata figure.", "    delivered = [m for m in record_metrics if m[\"metric\"] == ess_metrics.METRIC_QA_REPORT_DELIVERED]", "    assert delivered, \"expected an ess.qa_report.delivered metric\"", "    out_of_sample = [", "        m for m in record_metrics if m[\"metric\"] == ess_metrics.METRIC_QA_REPORT_OUT_OF_SAMPLE", "    ]", "    assert out_of_sample, \"expected an ess.qa_report.out_of_sample gauge\"", "    assert out_of_sample[-1][\"value\"] == float(doc.metadata.out_of_sample_count)", "", "", "async def test_full_run_report_key_is_unique_per_run(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, canned_grader", ") -> None:", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-c\",", "        )", "", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=False, sample_size=50))", "    await cli_mod._run()", "    await cli_mod._run()", "", "    # DAT-8141: two runs now yield two PAIRS. Assert the pairing rather than a raw", "    # count, so a future third artifact cannot slip past by inflating the total.", "    json_keys = sorted(k for k in fake_s3.store if \"/report-\" in k and k.endswith(\".json\"))", "    html_keys = sorted(k for k in fake_s3.store if \"/report-\" in k and k.endswith(\".html\"))", "    assert len(json_keys) == 2  # no same-day overwrite", "    assert [k.removesuffix(\".json\") for k in json_keys] == [", "        k.removesuffix(\".html\") for k in html_keys", "    ]", "", "", "# --------------------------------------------------------------------------- #", "# Rotation: sequential non-overlap + budget-drop pickup.", "# --------------------------------------------------------------------------- #", "", "", "async def test_rotation_sequential_runs_grade_non_overlapping_sets(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, canned_grader", ") -> None:", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        for _ in range(4):", "            await _seed_event(", "                ac,", "                category_id=category_id,", "                type_id=type_id,", "                cleanup=cleanup_ess_tables,", "                event_class=\"create\",", "                marker=\"qa-c\",", "            )", "        for _ in range(4):", "            await _seed_event(", "                ac,", "                category_id=category_id,", "                type_id=type_id,", "                cleanup=cleanup_ess_tables,", "                event_class=\"merge\",", "                marker=\"qa-m\",", "            )", "", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=True, sample_size=3))", "", "    await cli_mod._run()  # run 1", "    run1 = _report_documents(fake_s3)[-1]", "    assert qa_cursor_store_state_written(fake_s3)  # cursor object committed", "", "    await cli_mod._run()  # run 2 reads run-1's committed cursor", "    docs = _report_documents(fake_s3)", "    run2 = docs[-1]", "", "    ids1 = set(run1.sampled_event_ids)", "    ids2 = set(run2.sampled_event_ids)", "    assert ids1 and ids2", "    assert ids1.isdisjoint(ids2)  # each run grades a DIFFERENT set", "    assert run2.metadata.cursor_before == run1.metadata.cursor_after", "", "    # out_of_sample is the CURSOR-BOUNDED backlog: run 2 reports FEWER remaining than", "    # run 1 (the old total_eligible-based count reported the same on both runs).", "    # Each run removes exactly what it graded, whatever else the DB holds.", "    assert run2.metadata.out_of_sample_count < run1.metadata.out_of_sample_count", "    assert run2.metadata.out_of_sample_count == run1.metadata.out_of_sample_count - len(ids2)", "", "", "async def test_rotation_budget_dropped_event_picked_up_next_run(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, canned_grader", ") -> None:", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        created_ids = [", "            await _seed_event(", "                ac,", "                category_id=category_id,", "                type_id=type_id,", "                cleanup=cleanup_ess_tables,", "                event_class=\"create\",", "                marker=\"qa-c\",", "            )", "            for _ in range(3)", "        ]", "    assert created_ids  # ordering is by recency; the oldest is dropped by the tight budget", "", "    # Tight budget forces run 1 to drop its oldest selected event.", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=True, sample_size=3, max_input_chars=700))", "    await cli_mod._run()", "    run1 = _report_documents(fake_s3)[-1]", "    dropped = set(created_ids) - set(run1.sampled_event_ids)", "    assert dropped  # at least one event dropped by the budget", "    assert run1.metadata.out_of_sample_count >= len(dropped)", "", "    await cli_mod._run()", "    run2 = _report_documents(fake_s3)[-1]", "    # A dropped event is re-selectable next run (cursor advanced only to the", "    # oldest GRADED event) -- no permanent skip.", "    assert dropped & set(run2.sampled_event_ids)", "", "", "# --------------------------------------------------------------------------- #", "# Cursor fail-closed + grader-failure path.", "# --------------------------------------------------------------------------- #", "", "", "async def test_corrupt_cursor_fails_closed(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, canned_grader", ") -> None:", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-c\",", "        )", "", "    cfg = _cfg(rotation_enabled=True, sample_size=10)", "    _use_cfg(monkeypatch, cfg)", "    fake_s3.store[cfg.cursor_state_key] = b\"{ not valid json\"  # pre-write corrupt state", "", "    code = await cli_mod._run()", "", "    assert code == 1", "    assert _report_documents(fake_s3) == []  # refused to run; no report delivered", "", "", "async def test_grader_failure_delivers_the_deterministic_half_without_committing(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, record_metrics", ") -> None:", "    \"\"\"End-to-end twin of the CLI unit test (PR #495 review).", "", "    This used to assert that a grader failure delivered NOTHING. That is the defect:", "    AC2 requires the linkage measures to be visible without LLM judgment, but they", "    only ever reached S3 inside the report envelope, which was only built after a", "    successful grade(). Every LLM failure therefore suppressed the deterministic", "    half -- most likely during a total linkage outage, when every sampled event has", "    zero links and the grader is at its most likely to fail.", "", "    Run against a real database so the deterministic measures are computed from real", "    SQL rather than a stubbed sampler.", "    \"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-c\",", "        )", "", "    async def _boom(self: QAReportGraderClient, *, prepared) -> QAReportGradeResult:  # noqa: ANN001", "        raise AIServiceException(\"both providers failed\")", "", "    monkeypatch.setattr(QAReportGraderClient, \"grade\", _boom)", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=True, sample_size=10))", "", "    code = await cli_mod._run()", "", "    assert code == 1, \"a degraded run is still a failed run\"", "    documents = _report_documents(fake_s3)", "    assert len(documents) == 1, \"the deterministic half must still reach S3\"", "    assert not qa_cursor_store_state_written(fake_s3), (", "        \"an ungraded window must not advance the watermark -- doing so would skip \"", "        \"those events permanently on the next rotation run\"", "    )", "    assert any(m[\"metric\"] == \"ess.qa_report.grade_failed\" for m in record_metrics)", "    assert any(m[\"metric\"] == \"ess.qa_report.delivered_degraded\" for m in record_metrics)", "", "    document = documents[0]", "    assert document.grading_state == \"failed\"", "    assert document.grading_failure == \"grading\"", "    assert document.llm_report is None, \"no grades may be invented\"", "    assert document.metadata.chat_model is None", "    assert document.metadata.flagged_count is None", "    # The deterministic half, computed from real SQL, survived the grader failure.", "    assert document.metadata.linkage_health is not None", "    assert document.metadata.sampled_zero_link_count is not None", "    assert document.metadata.linkage_coverage, \"coverage buckets must be present\"", "    assert document.events, \"event context must survive too\"", "", "", "def qa_cursor_store_state_written(store: _InMemoryS3) -> bool:", "    return any(k.endswith(\"/_state/cursor.json\") for k in store.store)", "", "", "# --------------------------------------------------------------------------- #", "# DAT-8141: the human-readable sibling.", "# --------------------------------------------------------------------------- #", "", "", "async def test_full_run_delivers_readable_html_beside_the_json(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, canned_grader, record_metrics", ") -> None:", "    \"\"\"AC1 end-to-end: a reviewer sees WHAT a graded event said, no DB lookup.", "", "    Asserted against the real delivered pair rather than a rendered fixture, so a", "    break anywhere in sampler -> envelope -> renderer surfaces here.", "    \"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-html-c\",", "        )", "        await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"merge\",", "            marker=\"qa-html-m\",", "        )", "", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=False, sample_size=50))", "    assert await cli_mod._run() == 0", "", "    documents = _report_documents(fake_s3)", "    pages = _report_html(fake_s3)", "    assert len(documents) == 1 and len(pages) == 1", "", "    document, page = documents[0], pages[0]", "", "    # AC2: the machine-readable form is still a valid QAReportDocument (it parsed).", "    # AC1: every graded event carries context, and its summary is IN the page.", "    assert {e.event_id for e in document.events} == set(document.sampled_event_ids)", "    assert document.events, \"no context rendered\"", "    for ctx in document.events:", "        assert ctx.summary in page", "", "    # Self-contained: no script, no network fetches.", "    assert \"<script\" not in page.lower()", "    assert \"https://\" not in page", "", "", "# --------------------------------------------------------------------------- #", "# DAT-8294: deterministic entity-linkage measures.", "#", "# This module seeded NO ``SourceEventEntity`` rows before this ticket and no", "# DataLake ``raw_events`` at all, so the fixtures below are new. ``raw_events``", "# and ``source_event_entities`` are cleaned per test: the shared", "# ``cleanup_ess_tables`` tracker covers neither.", "# --------------------------------------------------------------------------- #", "", "_LINKAGE_ENTITY = {", "    \"entity_type\": \"CVW\",", "    \"role\": \"subject\",", "    \"confidence\": 0.9,", "}", "", "", "@pytest.fixture", "async def linkage_cleanup(cleanup_ess_tables):", "    \"\"\"Track the DataLake raw-event CHAINS and accelerate entity rows a test seeds.", "", "    ``raw_event_seeds`` holds :class:`RawEventSeed` values, not bare ids. Deleting", "    the raw event alone leaves its four parents behind -- article, sent SQS", "    message, EC layer-one activity, doc_article_map -- and every lineage test", "    seeds a fresh chain, so a bare-id teardown grew the DataLake scratch database", "    by four orphan rows per test per run. ``cleanup_raw_event_chain`` removes each", "    chain in FK order instead.", "    \"\"\"", "    state: dict[str, list] = {\"raw_event_seeds\": [], \"entity_event_ids\": []}", "    yield state", "", "    if state[\"entity_event_ids\"]:", "        async with sessionmanager_accelerate.session() as ac:", "            await ac.execute(", "                delete(SourceEventEntity).where(", "                    SourceEventEntity.event_id.in_(state[\"entity_event_ids\"])", "                )", "            )", "            await ac.commit()", "    if state[\"raw_event_seeds\"]:", "        async with sessionmanager_datalake.session() as dl:", "            await cleanup_raw_event_chain(dl, state[\"raw_event_seeds\"])", "", "", "async def _link_entity(", "    ac: Any,", "    *,", "    event_id: UUID,", "    entity_id: UUID,", "    directness: EntityDirectness,", "    linkage_cleanup: dict[str, list],", ") -> None:", "    \"\"\"Attach one entity row of the given directness to a seeded source event.\"\"\"", "    linkage_cleanup[\"entity_event_ids\"].append(event_id)", "    ac.add(", "        SourceEventEntity(", "            event_id=event_id,", "            entity_id=entity_id,", "            role=\"subject\",", "            confidence=Decimal(\"0.900\"),", "            directness=directness,", "        )", "    )", "    await ac.commit()", "", "", "async def _seed_lineage(", "    *,", "    event_id: UUID,", "    category_id: UUID,", "    type_id: UUID,", "    entities_involved: Any,", "    linkage_cleanup: dict[str, list],", ") -> UUID:", "    \"\"\"Point one of an event's document rows at a real DataLake raw event.", "", "    ``_seed_event`` gives every document a RANDOM ``raw_event_id`` that resolves", "    to nothing, which is the ``not_assessed`` case. This rewrites one of them to a", "    raw event that actually exists, so AC1 has evidence to read.", "    \"\"\"", "    raw_event_id = uuid4()", "    async with sessionmanager_datalake.session() as dl:", "        seed: RawEventSeed = await seed_raw_event(", "            dl,", "            raw_event_id=raw_event_id,", "            doc_id=_new_doc_id(),", "            summary=\"lineage raw event\",", "            event_category_id=category_id,", "            event_type_id=type_id,", "            entities_involved=entities_involved,", "        )", "    # Registered AFTER the seed returns, so teardown gets the whole chain the call", "    # actually created rather than the raw-event id alone.", "    linkage_cleanup[\"raw_event_seeds\"].append(seed)", "    async with sessionmanager_accelerate.session() as ac:", "        await ac.execute(", "            text(", "                \"UPDATE event_synth.source_event_documents SET raw_event_id = :raw \"", "                \"WHERE id = (SELECT id FROM event_synth.source_event_documents \"", "                \"            WHERE event_id = :evt ORDER BY id LIMIT 1)\"", "            ),", "            {\"raw\": raw_event_id, \"evt\": str(event_id)},", "        )", "        await ac.commit()", "    return raw_event_id", "", "", "# ------------------------------------------------------------- AC2: coverage --", "", "", "async def test_population_coverage_reports_a_bucket_per_day_over_the_window(", "    cleanup_ess_tables, mirrored_event_type, linkage_cleanup", ") -> None:", "    \"\"\"Every day in the lookback yields a bucket, empty days included.", "", "    A grouped aggregate alone emits no row for a day with no eligible event --", "    exactly the day that must read ``not_assessed`` rather than vanish.", "    \"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-cov\",", "            first_detected_on=datetime.now(UTC) - timedelta(days=2),", "        )", "", "    async with sessionmanager_accelerate.read_session() as ac:", "        result = await QASampleRepository(ac).sample_recent(_cfg(lookback_days=7), cursor=None)", "", "    assert len(result.coverage_buckets) == 8  # 7 days of lookback, inclusive of both edges", "    assert result.coverage_buckets[0].partial and result.coverage_buckets[-1].partial", "    assert any(b.eligible > 0 for b in result.coverage_buckets)", "", "", "async def test_an_interval_with_events_and_zero_direct_links_reports_failed(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, canned_grader, linkage_cleanup", ") -> None:", "    \"\"\"AC2 end-to-end, with the grader STUBBED: the signal needs no LLM.", "", "    Seeds events into a window and links none of them. The report must say", "    ``failed`` and must say so from counting alone.", "    \"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        for _ in range(2):", "            await _seed_event(", "                ac,", "                category_id=category_id,", "                type_id=type_id,", "                cleanup=cleanup_ess_tables,", "                event_class=\"create\",", "                marker=\"qa-nolink\",", "                first_detected_on=datetime.now(UTC) - timedelta(days=1),", "            )", "", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=False, sample_size=50, lookback_days=2))", "    assert await cli_mod._run() == 0", "", "    metadata = _report_documents(fake_s3)[-1].metadata", "    assert metadata.linkage_health == \"failed\"", "    assert any(b.eligible > 0 and b.linked == 0 for b in metadata.linkage_coverage)", "    # AC2's literal ask: the graded sample's own zero-link count reflects it too.", "    assert metadata.sampled_zero_link_count == metadata.sampled_count", "", "", "async def test_owner_only_links_do_not_count_toward_coverage(", "    cleanup_ess_tables, mirrored_event_type, linkage_cleanup", ") -> None:", "    \"\"\"A ``CAUSALLY_IMPLICATED`` row is an entity row, but not a direct link.", "", "    Owner rows are computed FROM direct seeds, so counting them would let an", "    owner-only event mask a total direct-insert failure.", "    \"\"\"", "    category_id, type_id = mirrored_event_type", "    seed = None", "    async with sessionmanager_accelerate.session() as ac:", "        seed = await seed_platform_entity(ac, entity_type=AccountType.CVW)", "        event_id = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-owner-only\",", "            first_detected_on=datetime.now(UTC) - timedelta(days=1),", "        )", "        await _link_entity(", "            ac,", "            event_id=event_id,", "            entity_id=seed.entity_id,", "            directness=EntityDirectness.CAUSALLY_IMPLICATED,", "            linkage_cleanup=linkage_cleanup,", "        )", "", "    async with sessionmanager_accelerate.read_session() as ac:", "        result = await QASampleRepository(ac).sample_recent(", "            _cfg(sample_size=50, lookback_days=2), cursor=None", "        )", "", "    assert result.direct_link_counts[event_id] == 0  # owner rows are not direct links", "", "", "async def test_direct_links_are_counted_and_report_healthy(", "    cleanup_ess_tables, mirrored_event_type, linkage_cleanup", ") -> None:", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        seed = await seed_platform_entity(ac, entity_type=AccountType.CVW)", "        event_id = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"merge\",", "            marker=\"qa-linked\",", "            first_detected_on=datetime.now(UTC) - timedelta(hours=2),", "        )", "        await _link_entity(", "            ac,", "            event_id=event_id,", "            entity_id=seed.entity_id,", "            directness=EntityDirectness.DIRECTLY_MENTIONED,", "            linkage_cleanup=linkage_cleanup,", "        )", "", "    async with sessionmanager_accelerate.read_session() as ac:", "        result = await QASampleRepository(ac).sample_recent(", "            _cfg(sample_size=50, lookback_days=1), cursor=None", "        )", "", "    assert result.direct_link_counts[event_id] == 1", "    today = [b for b in result.coverage_buckets if b.eligible > 0]", "    assert today and all(b.linked >= 1 for b in today)", "", "", "async def test_entity_cap_does_not_reduce_the_reported_direct_link_count(", "    cleanup_ess_tables, mirrored_event_type, linkage_cleanup", ") -> None:", "    \"\"\"The pre-trim guarantee, against real rows and the real cap.\"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        event_id = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-capped\",", "            first_detected_on=datetime.now(UTC) - timedelta(hours=2),", "        )", "        for _ in range(3):", "            seed = await seed_platform_entity(ac, entity_type=AccountType.CVW)", "            await _link_entity(", "                ac,", "                event_id=event_id,", "                entity_id=seed.entity_id,", "                directness=EntityDirectness.DIRECTLY_MENTIONED,", "                linkage_cleanup=linkage_cleanup,", "            )", "", "    async with sessionmanager_accelerate.read_session() as ac:", "        result = await QASampleRepository(ac).sample_recent(", "            _cfg(sample_size=50, lookback_days=1, max_entities_per_event=1), cursor=None", "        )", "", "    row = next(r for r in result.rows if r.event_id == event_id)", "    assert len(row.entities) == 1  # the grader saw one", "    assert result.direct_link_counts[event_id] == 3  # the report states three", "", "", "# ------------------------------------------------------------------ AC1 --", "", "", "async def test_ac1_event_that_carried_entities_with_no_links_is_counted_as_loss(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, canned_grader, linkage_cleanup", ") -> None:", "    \"\"\"AC1's positive case, through the real cross-database lineage read.\"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        entity_seed = await seed_platform_entity(ac, entity_type=AccountType.CVW)", "        event_id = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-ac1-loss\",", "            first_detected_on=datetime.now(UTC) - timedelta(hours=2),", "        )", "    await _seed_lineage(", "        event_id=event_id,", "        category_id=category_id,", "        type_id=type_id,", "        entities_involved=[{**_LINKAGE_ENTITY, \"entity_id\": str(entity_seed.entity_id)}],", "        linkage_cleanup=linkage_cleanup,", "    )", "", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=False, sample_size=50, lookback_days=1))", "    assert await cli_mod._run() == 0", "", "    document = _report_documents(fake_s3)[-1]", "    state = {e.event_id: e.entity_loss_state for e in document.events}", "    assert state[event_id] == \"loss\"", "    assert document.metadata.unexpected_entity_loss_count >= 1", "", "", "async def test_ac1_event_whose_raw_events_carried_no_entities_is_not_a_loss(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, canned_grader, linkage_cleanup", ") -> None:", "    \"\"\"AC1's negative case, and it must NOT come back ``not_assessed`` either.\"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        event_id = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-ac1-clean\",", "            first_detected_on=datetime.now(UTC) - timedelta(hours=2),", "        )", "    await _seed_lineage(", "        event_id=event_id,", "        category_id=category_id,", "        type_id=type_id,", "        entities_involved=[],", "        linkage_cleanup=linkage_cleanup,", "    )", "", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=False, sample_size=50, lookback_days=1))", "    assert await cli_mod._run() == 0", "", "    document = _report_documents(fake_s3)[-1]", "    state = {e.event_id: e.entity_loss_state for e in document.events}", "    assert state[event_id] == \"no_loss\"", "", "", "async def test_ac1_unresolvable_lineage_is_not_assessed(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, canned_grader, linkage_cleanup", ") -> None:", "    \"\"\"``_seed_event`` gives every document a RANDOM raw_event_id.", "", "    Those resolve to no DataLake row, so every event in this module's existing", "    fixtures is the unresolved case -- and unresolved must read ``not_assessed``,", "    never ``no_loss``.", "    \"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        event_id = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-ac1-unknown\",", "            first_detected_on=datetime.now(UTC) - timedelta(hours=2),", "        )", "", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=False, sample_size=50, lookback_days=1))", "    assert await cli_mod._run() == 0", "", "    document = _report_documents(fake_s3)[-1]", "    state = {e.event_id: e.entity_loss_state for e in document.events}", "    assert state[event_id] == \"not_assessed\"", "", "", "async def test_ac1_state_set_equals_the_graded_set(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, canned_grader, linkage_cleanup", ") -> None:", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        for _ in range(3):", "            await _seed_event(", "                ac,", "                category_id=category_id,", "                type_id=type_id,", "                cleanup=cleanup_ess_tables,", "                event_class=\"create\",", "                marker=\"qa-ac1-set\",", "                first_detected_on=datetime.now(UTC) - timedelta(hours=2),", "            )", "", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=False, sample_size=50, lookback_days=1))", "    assert await cli_mod._run() == 0", "", "    document = _report_documents(fake_s3)[-1]", "    with_state = {e.event_id for e in document.events if e.entity_loss_state}", "    assert with_state == set(document.sampled_event_ids)", "", "", "# --------------------------------------------------------- page + contract --", "", "", "async def test_linkage_measures_render_on_the_delivered_page(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, canned_grader, linkage_cleanup", ") -> None:", "    \"\"\"The HTML page, not the metrics, is the authoritative artifact.\"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-linkage-html\",", "            first_detected_on=datetime.now(UTC) - timedelta(hours=2),", "        )", "", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=False, sample_size=50, lookback_days=2))", "    assert await cli_mod._run() == 0", "", "    page = _report_html(fake_s3)[-1]", "    assert 'data-testid=\"linkage-health\"' in page", "    assert 'data-testid=\"linkage-intervals\"' in page", "    assert 'data-testid=\"sampled-zero-links\"' in page", "    assert 'data-testid=\"unexpected-entity-loss\"' in page", "    assert 'data-testid=\"event-direct-links\"' in page", "    assert 'data-testid=\"event-entity-loss\"' in page", "", "", "async def test_empty_window_still_exits_zero_without_delivering_or_advancing(", "    monkeypatch, cleanup_ess_tables, mirrored_event_type, fake_s3, canned_grader", ") -> None:", "    \"\"\"The job's exit contract is unchanged by this ticket.", "", "    Nothing eligible in the window: exit 0, no S3 object, cursor untouched, and the", "    population figures on the existing ``empty_sample`` line so an empty window", "    stays distinguishable from a linkage failure.", "    \"\"\"", "    # A zero-length lookback selects nothing regardless of what else is in the DB.", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=True, sample_size=10, lookback_days=1))", "    async with sessionmanager_accelerate.session() as ac:", "        await ac.execute(", "            text(", "                \"UPDATE event_synth.source_events SET first_detected_on = \"", "                \"first_detected_on - interval '400 days' WHERE id = ANY(:ids)\"", "            ),", "            {\"ids\": [str(i) for i in cleanup_ess_tables[\"accelerate_source_event_ids\"]]},", "        )", "        await ac.commit()", "", "    with structlog.testing.capture_logs() as cap:", "        code = await cli_mod._run()", "", "    assert code == 0", "    assert _report_documents(fake_s3) == []", "    assert not qa_cursor_store_state_written(fake_s3)", "    empty = [e for e in cap if e.get(\"event\") == \"ess.qa_report.empty_sample\"]", "    assert empty, \"expected ess.qa_report.empty_sample\"", "    assert \"linkage_health\" in empty[-1]", "    assert \"population_eligible\" in empty[-1]", "", "", "# --------------------------------------------------------------------------- #", "# DAT-8294 plan 02: entity identity and truncation provenance, against the real", "# ``ent.entities`` join.", "# --------------------------------------------------------------------------- #", "", "", "async def test_entity_evidence_carries_the_real_display_name_and_type(", "    cleanup_ess_tables, mirrored_event_type, linkage_cleanup", ") -> None:", "    \"\"\"AC3 end to end: the name and type come from ``ent.entities``, not a fixture.", "", "    The unit tests hand-build ``_RawEntity`` rows, so only this one proves the join", "    itself resolves -- and that the ``AccountType`` enum arrives as a plain code", "    rather than failing DTO validation.", "    \"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        seed = await seed_platform_entity(", "            ac, entity_type=AccountType.CVW, display_name=\"Northwind Traders\"", "        )", "        event_id = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-named-entity\",", "            first_detected_on=datetime.now(UTC) - timedelta(hours=2),", "        )", "        await _link_entity(", "            ac,", "            event_id=event_id,", "            entity_id=seed.entity_id,", "            directness=EntityDirectness.DIRECTLY_MENTIONED,", "            linkage_cleanup=linkage_cleanup,", "        )", "", "    async with sessionmanager_accelerate.read_session() as ac:", "        result = await QASampleRepository(ac).sample_recent(", "            _cfg(sample_size=50, lookback_days=1), cursor=None", "        )", "", "    row = next(r for r in result.rows if r.event_id == event_id)", "    assert [(e.display_name, e.entity_type) for e in row.entities] == [(\"Northwind Traders\", \"CVW\")]", "    assert result.entity_loss_causes[event_id] == frozenset()", "    assert result.truncated_entity_names[event_id] == frozenset()", "", "", "async def test_an_over_cap_display_name_is_truncated_and_marked(", "    cleanup_ess_tables, mirrored_event_type, linkage_cleanup", ") -> None:", "    \"\"\"``display_name`` is unbounded ``Text``; the cap is what keeps the prompt bounded.", "", "    Seeded at a real over-cap length so the truncation runs against a database value", "    rather than a hand-built DTO, and the marker is asserted per entity.", "    \"\"\"", "    long_name = \"Northwestern Intercontinental Logistics And Freight Holdings Incorporated\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        seed = await seed_platform_entity(ac, entity_type=AccountType.CVW, display_name=long_name)", "        event_id = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-long-entity-name\",", "            first_detected_on=datetime.now(UTC) - timedelta(hours=2),", "        )", "        await _link_entity(", "            ac,", "            event_id=event_id,", "            entity_id=seed.entity_id,", "            directness=EntityDirectness.DIRECTLY_MENTIONED,", "            linkage_cleanup=linkage_cleanup,", "        )", "", "    async with sessionmanager_accelerate.read_session() as ac:", "        result = await QASampleRepository(ac).sample_recent(", "            _cfg(sample_size=50, lookback_days=1, max_entity_name_chars=32), cursor=None", "        )", "", "    row = next(r for r in result.rows if r.event_id == event_id)", "    assert row.entities[0].display_name == long_name[:32]", "    assert result.entity_loss_causes[event_id] == frozenset({\"name_truncated\"})", "    assert result.truncated_entity_names[event_id] == frozenset({seed.entity_id})", "", "", "async def test_the_sampler_cap_is_recorded_against_the_event_it_capped(", "    cleanup_ess_tables, mirrored_event_type, linkage_cleanup", ") -> None:", "    \"\"\"The aggregate counter says a cap fired; the marker says on which event.\"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        event_id = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-capped-provenance\",", "            first_detected_on=datetime.now(UTC) - timedelta(hours=2),", "        )", "        for _ in range(3):", "            seed = await seed_platform_entity(ac, entity_type=AccountType.CVW)", "            await _link_entity(", "                ac,", "                event_id=event_id,", "                entity_id=seed.entity_id,", "                directness=EntityDirectness.DIRECTLY_MENTIONED,", "                linkage_cleanup=linkage_cleanup,", "            )", "", "    async with sessionmanager_accelerate.read_session() as ac:", "        result = await QASampleRepository(ac).sample_recent(", "            _cfg(sample_size=50, lookback_days=1, max_entities_per_event=1), cursor=None", "        )", "", "    assert result.entity_loss_causes[event_id] == frozenset({\"entity_cap\"})", "    assert len(next(r for r in result.rows if r.event_id == event_id).entities) == 1", "", "", "# --------------------------------------------------------------------------- #", "# DAT-8294 plan 03: the grader's plausibility verdict, end to end.", "# --------------------------------------------------------------------------- #", "", "", "async def test_an_implausible_linkage_verdict_flags_the_event_end_to_end(", "    monkeypatch,", "    # Declared before linkage_cleanup: fixtures finalize in reverse setup order,", "    # so the ent.entities delete must be set up FIRST to run LAST -- after", "    # linkage_cleanup has cleared the source_event_entities rows that reference", "    # it (source_event_entities_entity_id_fkey is RESTRICT).", "    cleanup_platform_entity_seeds,", "    cleanup_ess_tables,", "    mirrored_event_type,", "    linkage_cleanup,", "    fake_s3,", ") -> None:", "    \"\"\"R5 through the whole job: verdict -> flagged_count -> flagged HTML section.", "", "    The grader is canned (the REAL model is exercised only by the Task 6 gate), but", "    everything downstream of it is the production path: semantic validation, the", "    shared flag predicate, the stored envelope, and the delivered page.", "    \"\"\"", "    category_id, type_id = mirrored_event_type", "    async with sessionmanager_accelerate.session() as ac:", "        seed = await seed_platform_entity(ac, entity_type=AccountType.CVW)", "        cleanup_platform_entity_seeds.append(seed)", "        event_id = await _seed_event(", "            ac,", "            category_id=category_id,", "            type_id=type_id,", "            cleanup=cleanup_ess_tables,", "            event_class=\"create\",", "            marker=\"qa-implausible\",", "            first_detected_on=datetime.now(UTC) - timedelta(days=1),", "        )", "        await _link_entity(", "            ac,", "            event_id=event_id,", "            entity_id=seed.entity_id,", "            directness=EntityDirectness.DIRECTLY_MENTIONED,", "            linkage_cleanup=linkage_cleanup,", "        )", "", "    async def _grade(self: QAReportGraderClient, *, prepared) -> QAReportGradeResult:  # noqa: ANN001", "        return QAReportGradeResult(", "            output=QAReportOutput(", "                per_event=[", "                    QAEventGrade(", "                        event_id=e.event_id,", "                        event_valid=True,", "                        merge_correct=None", "                        if (e.event_class == \"create\" or len(e.docs) < 2)", "                        else True,", "                        issues=[],", "                        explanation=\"the event itself reads fine\",", "                        confidence=0.9,", "                        entity_linkage_plausible=False if e.entities else None,", "                        entity_linkage_explanation=(", "                            \"the linked company is not a participant\" if e.entities else None", "                        ),", "                    )", "                    for e in prepared.events", "                ],", "                duplicate_pairs=[],", "            ),", "            chat_model_used=ChatModel.GPT_6_LUNA.value,", "            fallback_used=False,", "        )", "", "    monkeypatch.setattr(QAReportGraderClient, \"grade\", _grade)", "    _use_cfg(monkeypatch, _cfg(rotation_enabled=False, sample_size=50, lookback_days=2))", "", "    code = await cli_mod._run()", "", "    assert code == 0", "    doc = _report_documents(fake_s3)[0]", "    graded = {g.event_id: g for g in doc.llm_report.per_event}", "    assert graded[event_id].entity_linkage_plausible is False", "    # The shared predicate reached the stored count without the CLI being touched.", "    assert doc.metadata.flagged_count >= 1", "    html = _report_html(fake_s3)[0]", "    assert 'data-testid=\"event-linkage-verdict-implausible\"' in html", "    assert \"the linked company is not a participant\" in html", "    assert 'data-testid=\"flag-reason-entity_linkage\"' in html"], "blocks": [{"start": 1, "end": 67, "label": "Imports and module setup"}, {"start": 68, "end": 90, "label": "def _cfg"}, {"start": 91, "end": 94, "label": "def _new_doc_id"}, {"start": 95, "end": 178, "label": "def _seed_event"}, {"start": 179, "end": 208, "label": "def canned_grader"}, {"start": 209, "end": 223, "label": "def _keep_shared_session_managers"}, {"start": 224, "end": 233, "label": "def _report_documents"}, {"start": 234, "end": 246, "label": "def _report_html"}, {"start": 247, "end": 270, "label": "def test_a_statement_past_its_budget_is_cancelled_by_postgres"}, {"start": 271, "end": 317, "label": "def test_detail_fetch_drops_an_event_invalidated_after_the_population_read"}, {"start": 318, "end": 347, "label": "def test_sampler_classifies_create_and_merge"}, {"start": 348, "end": 389, "label": "def test_sampler_both_class_coverage_and_backfill"}, {"start": 390, "end": 416, "label": "def test_sampler_single_class_only_creates"}, {"start": 417, "end": 455, "label": "def test_sampler_same_first_detected_on_orders_by_id_desc"}, {"start": 456, "end": 494, "label": "def test_sampler_total_eligible_delta_matches_seeded"}, {"start": 495, "end": 534, "label": "def test_sampler_keeps_highest_source_tier_docs"}, {"start": 535, "end": 584, "label": "def test_full_run_delivers_report_covering_three_checks"}, {"start": 585, "end": 617, "label": "def test_full_run_report_key_is_unique_per_run"}, {"start": 618, "end": 664, "label": "def test_rotation_sequential_runs_grade_non_overlapping_sets"}, {"start": 665, "end": 702, "label": "def test_rotation_budget_dropped_event_picked_up_next_run"}, {"start": 703, "end": 726, "label": "def test_corrupt_cursor_fails_closed"}, {"start": 727, "end": 783, "label": "def test_grader_failure_delivers_the_deterministic_half_without_committing"}, {"start": 784, "end": 792, "label": "def qa_cursor_store_state_written"}, {"start": 793, "end": 856, "label": "def test_full_run_delivers_readable_html_beside_the_json"}, {"start": 857, "end": 883, "label": "def linkage_cleanup"}, {"start": 884, "end": 905, "label": "def _link_entity"}, {"start": 906, "end": 949, "label": "def _seed_lineage"}, {"start": 950, "end": 977, "label": "def test_population_coverage_reports_a_bucket_per_day_over_the_window"}, {"start": 978, "end": 1008, "label": "def test_an_interval_with_events_and_zero_direct_links_reports_failed"}, {"start": 1009, "end": 1045, "label": "def test_owner_only_links_do_not_count_toward_coverage"}, {"start": 1046, "end": 1078, "label": "def test_direct_links_are_counted_and_report_healthy"}, {"start": 1079, "end": 1116, "label": "def test_entity_cap_does_not_reduce_the_reported_direct_link_count"}, {"start": 1117, "end": 1149, "label": "def test_ac1_event_that_carried_entities_with_no_links_is_counted_as_loss"}, {"start": 1150, "end": 1180, "label": "def test_ac1_event_whose_raw_events_carried_no_entities_is_not_a_loss"}, {"start": 1181, "end": 1209, "label": "def test_ac1_unresolvable_lineage_is_not_assessed"}, {"start": 1210, "end": 1236, "label": "def test_ac1_state_set_equals_the_graded_set"}, {"start": 1237, "end": 1264, "label": "def test_linkage_measures_render_on_the_delivered_page"}, {"start": 1265, "end": 1303, "label": "def test_empty_window_still_exits_zero_without_delivering_or_advancing"}, {"start": 1304, "end": 1345, "label": "def test_entity_evidence_carries_the_real_display_name_and_type"}, {"start": 1346, "end": 1385, "label": "def test_an_over_cap_display_name_is_truncated_and_marked"}, {"start": 1386, "end": 1424, "label": "def test_the_sampler_cap_is_recorded_against_the_event_it_capped"}, {"start": 1425, "end": 1504, "label": "def test_an_implausible_linkage_verdict_flags_the_event_end_to_end"}], "lineCount": 1504, "sha256": "16d0bf07e7eb413610d42fc4507d9512f11a48174eb3225c6857b74af9debcdc", "endsWithNewline": true});
